<script setup lang="ts">
import FreightLines from '~/components/freight/FreightLines.vue'
const {t}=useI18n(),route=useRoute(),staff=useStaffStore(),warehouses=useWarehouseStore(),{bizErrorMessage}=useBizError()
const ready=ref(false)
let disposed=false
const warehouseId=computed(()=>warehouses.currentWarehouse?.id||null),canEdit=computed(()=>ready.value&&!!staff.refreshed&&!!staff.staffInfo&&staff.hasPermission('freight_edit'))
const data=ref<any>(null),loading=ref(false),busy=ref(false),error=ref(''),reviewError=ref(''),reviewOpen=ref(false),selected=ref<any>(null)
const review=reactive({dn_id:'',review_status:'unreviewed',note:''}),stateFilter=ref('')
const endpoint=computed(()=>'/api/warehouse/carrier/freight/invoices/'+route.params.id)
let generation=0
const load=async()=>{if(!ready.value)return;const seq=++generation;data.value=null;error.value='';reviewOpen.value=false;loading.value=true;const result=await httpRequest<any>(endpoint.value,{headers:warehouseHeaders(warehouseId.value),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
const rows=computed(()=>data.value?.lines.filter((row:any)=>!stateFilter.value||row.state===stateFilter.value)||[])
const openReview=(row:any)=>{if(!canEdit.value||busy.value||data.value?.status!=='pending')return;selected.value=row;Object.assign(review,{dn_id:row.dn_id?String(row.dn_id):'',review_status:row.review_status,note:row.note||''});reviewError.value='';reviewOpen.value=true}
const save=async()=>{if(busy.value||!reviewOpen.value||!selected.value||data.value?.status!=='pending'||!canEdit.value)return;busy.value=true;reviewError.value='';const seq=generation;try{const result=await httpRequest<any>(endpoint.value+'/lines/'+selected.value.id,{method:'PUT',headers:warehouseHeaders(warehouseId.value),body:{revision:data.value.revision,review_status:review.review_status,note:review.note,...(review.dn_id&&review.review_status!=='external'?{dn_id:Number(review.dn_id)}:{})},onError:e=>{if(seq===generation)reviewError.value=bizErrorMessage(e)}});if(seq===generation&&result){data.value=result;reviewOpen.value=false}}finally{busy.value=false}}
const dirty=computed(()=>reviewOpen.value&&!!selected.value&&(review.dn_id!==String(selected.value.dn_id||'')||review.review_status!==selected.value.review_status||review.note!==(selected.value.note||'')))
useUnsavedForm(()=>dirty.value,()=>busy.value)
const closeReview=async(open:boolean)=>{if(open){reviewOpen.value=true;return}if(busy.value)return;if(dirty.value&&!await showConfirm(t('unsaved-form.title'),t('unsaved-form.message'),t('unsaved-form.leave'),t('unsaved-form.stay')))return;reviewOpen.value=false}
const reload=async()=>{if(busy.value)return;if(dirty.value&&!await showConfirm(t('unsaved-form.title'),t('unsaved-form.message'),t('unsaved-form.leave'),t('unsaved-form.stay')))return;await(ready.value?load():initialize())}
const confirm=async()=>{if(busy.value||!data.value||!canEdit.value)return;busy.value=true;error.value='';const seq=generation;try{const result=await httpRequest<any>(endpoint.value+'/confirm',{method:'PUT',headers:warehouseHeaders(warehouseId.value),body:{revision:data.value.revision,confirmed:data.value.status!=='confirmed'},onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation&&result)data.value=result}finally{busy.value=false}}
const download=async(suffix:string)=>{try{await downloadFile(endpoint.value+suffix,{headers:warehouseHeaders(warehouseId.value)},suffix==='/file'?data.value.file_name:'invoice.csv')}catch(e){error.value=bizErrorMessage(e as HttpRequestError)}}
watch([warehouseId,()=>route.params.id],load);const initialize=async()=>{ready.value=false;loading.value=true;error.value='';data.value=null;const current=await staff.getCurrentStaffInfo();if(disposed)return;if(!current){loading.value=false;error.value=t('action-results.failed');return}ready.value=true;load()};onMounted(initialize);onBeforeUnmount(()=>{disposed=true;generation++})
useHead({title:()=>data.value?.invoice_number||t('freight.title')})
</script>
<template><div class="freight-page w-scope"><header><div><NuxtLink to="/reports/freight">{{t('freight.title')}}</NuxtLink><h1>{{data?.invoice_number||t('freight.invoice')}}</h1></div><WButton :loading="loading" :disabled="busy" @click="reload">{{t('freight.reload')}}</WButton></header>
 <WAlert v-if="error" tone="block" :title="error"/>
 <WCard v-if="loading"><WEmptyState :title="t('common.status.loading')"/></WCard>
 <template v-else-if="data"><WCard><div class="summary"><div><small>{{t('nav.carrier')}}</small><strong>{{data.carrier_name}}</strong></div><div><small>{{t('freight.period')}}</small><strong>{{data.period_from}} — {{data.period_to}}</strong></div><div><small>{{t('freight.amount')}}</small><strong>{{data.currency}} {{data.total}}</strong></div><div><small>{{t('freight.unresolved')}}</small><strong>{{data.unresolved}} / {{data.line_count}}</strong></div><WStatus :tone="data.status==='confirmed'?'ok':'warn'">{{t('freight.states.'+data.status)}}</WStatus></div>
 <p>{{t('common.users.creator')}}: {{data.created_by?.name||data.created_by?.id||'\u2014'}} &middot; {{$dayjs(data.created_at,'YYYY-MM-DD HH:mm',data)}}</p><p v-if="data.confirmed_at">{{t('freight.states.confirmed')}}: {{data.confirmed_by?.name||data.confirmed_by?.id||'\u2014'}} &middot; {{$dayjs(data.confirmed_at,'YYYY-MM-DD HH:mm',data)}}</p>
 <p>{{t('freight.tolerance')}}: {{data.tolerance}} {{data.tolerance_type==='percent'?'%':data.currency}}</p>
 <footer><WButton @click="download('/file')">{{t('freight.original')}}</WButton><WButton @click="download('/export')">CSV</WButton><WButton @click="download('/export?format=xlsx')">Excel</WButton><WButton v-if="canEdit" variant="primary" :loading="busy" :disabled="data.status!=='confirmed'&&data.unresolved>0" @click="confirm">{{t(data.status==='confirmed'?'freight.reopen':'freight.confirm')}}</WButton></footer>
 </WCard><WAlert v-if="data.status==='confirmed'" tone="info" :title="t('freight.locked')"/>
 <WCard flush><div class="filters"><WFilterSelect v-model="stateFilter" :label="t('common.fields.status')" :options="['matched','difference','unmatched','no_estimate','currency_mismatch','accepted','disputed','external'].map(value=>({value,label:t('freight.states.'+value)}))"/></div><FreightLines :rows="rows" :editable="canEdit&&data.status==='pending'&&!busy" @review="openReview"/></WCard></template>
 <WModal :open="reviewOpen" @update:open="closeReview" :title="t('freight.review')" :closable="!busy"><p>{{selected?.tracking_number}} &middot; {{data?.currency}} {{selected?.amount}}</p><WAlert v-if="reviewError" tone="block" :title="reviewError"/><form id="freight-review" @submit.prevent="save"><WFormGrid>
 <WField :label="t('freight.link-dn')" :span="12"><WInput v-model="review.dn_id" type="number" min="1" step="1" :disabled="busy||review.review_status==='external'"/><small>{{t('freight.link-hint')}}</small></WField>
 <WField :label="t('common.fields.status')" :span="12"><WSelect v-model="review.review_status" :disabled="busy" :options="['unreviewed','accepted','disputed','external'].map(value=>({value,label:t('freight.states.'+value)}))"/></WField>
 <WField :label="t('freight.note')" :span="12"><WTextarea v-model="review.note" :maxlength="500" :required="review.review_status!=='unreviewed'" :disabled="busy"/></WField>
 </WFormGrid></form><template #footer><WButton type="submit" form="freight-review" variant="primary" :loading="busy">{{t('button.save')}}</WButton></template></WModal>
 </div></template>
<style scoped>.freight-page h1,.freight-page header>div,.summary>div{min-width:0;max-width:100%;overflow-wrap:anywhere}.freight-page :deep(.w-table td){max-width:260px;white-space:normal;overflow-wrap:anywhere}.freight-page{display:flex;flex-direction:column;gap:20px}header{display:flex;justify-content:space-between;align-items:start;gap:12px}h1{font-size:24px;margin:10px 0}.summary{display:flex;flex-wrap:wrap;gap:28px;align-items:center}.summary strong{display:block;margin-top:8px;font-size:18px}small,p{color:var(--w-text-3)}footer{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;padding-top:12px}.filters{padding:16px}a{color:var(--w-pri)}</style>
